package com.pandinila.broadband_management.controller;import com.pandinila.broadband_management.entity.*;import com.pandinila.broadband_management.entity.Enums.IncidentStatus;import com.pandinila.broadband_management.service.IncidentService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/incidents") public class IncidentController {private final IncidentService service;public IncidentController(IncidentService s){service=s;}@GetMapping public List<Incident> all(){return service.all();}@GetMapping("/{id}") public Incident one(@PathVariable Long id){return service.one(id);}@PostMapping("/proactive/{customerId}") public Incident proactive(@PathVariable Long customerId){return service.createProactive(customerId);}@PatchMapping("/{id}/status") public Incident status(@PathVariable Long id,@RequestParam IncidentStatus status,@RequestParam(required=false) String notes){return service.updateStatus(id,status,notes);}@PatchMapping("/{id}/assign") public Incident assign(@PathVariable Long id,@RequestParam(required=false) Long teamId,@RequestParam(required=false) Long engineerId){return service.assign(id,teamId,engineerId);}}
